// An ES module whose parts load through import() with a computed
// specifier: scriptc cannot compile that natively (R1.2), so it runs in a
// Node island. Its live bindings, classes and shared objects keep their
// meaning across the boundary.
export let count = 0;
export function bump() {
  count++;
  return count;
}
export class Counter {
  constructor(start) {
    this.value = start;
  }
  inc() {
    return ++this.value;
  }
}
export default function greet(name) {
  return `hello ${name}`;
}
export async function loadPart(name) {
  const part = await import(`./parts/${name}.js`);
  return part.label;
}
export const shared = { hits: 0 };
export function hit() {
  shared.hits++;
  return shared;
}
